function cupMediaContext(state:SeasonState,matchId:string,result?:MatchResult):MediaMatchContext|undefined{const c=getCupMatchContext(state,matchId);if(!c)return undefined;const club=getSelectedClub(state),opp=c.userSide==="home"?c.away:c.home,ctx:MediaMatchContext={matchKey:matchId,competition:c.tournament.definition.shortName,stage:c.match.stage,opponent:opp.name,venue:c.userSide==="home"?"Casa":"Fora",recentForm:state.recentForm,unavailable:club.players.filter(p=>p.injuryDays>0||p.suspensionMatches>0).slice(0,4).map(p=>p.name),relatedEvent:relatedMediaEvent(state)};if(result){const side=c.userSide,events=result.events.filter(e=>e.team===side),find=(id?:string)=>club.players.find(p=>p.id===id)?.name;Object.assign(ctx,{goalsFor:side==="home"?result.homeGoals:result.awayGoals,goalsAgainst:side==="home"?result.awayGoals:result.homeGoals,shotsFor:side==="home"?result.shotsHome:result.shotsAway,shotsAgainst:side==="home"?result.shotsAway:result.shotsHome,possessionFor:side==="home"?result.possessionHome:100-result.possessionHome,scorer:find(events.find(e=>e.type==="goal")?.playerId),redCard:find(events.find(e=>e.type==="red_card")?.playerId),injury:find(events.find(e=>e.type==="injury")?.playerId)});}return ctx;}
