  const selection=normalizeMatchdaySelection({...state,league} as SeasonState,selectedClub),livingWorldBase=state.livingWorld??createLivingWorld(selectedClub.name,state.competitionId);let livingWorld=userResult?worldAfterMatch(livingWorldBase,selectedClub,state.currentRound,gf,ga,state.competitionId):livingWorldBase;const careerResult=careerAfterRound(state.career??createManagerCareer(selectedClub,state.year),league,livingWorld,state.currentRound,state.year,state.baseSeed,userResult?{goalsFor:gf,goalsAgainst:ga}:undefined);livingWorld=careerResult.world;const userFixture=lastUserMatch?league.fixtures.find(f=>f.id===lastUserMatch.fixtureId):undefined,mediaWorld=userResult&&userFixture?mediaAfterMatch(state.mediaWorld,state.competitionId,selectedClub,state.currentRound,gf,ga,state.baseSeed,leagueMediaContext({...state,league} as SeasonState,userFixture,userResult)):hydrateMediaWorld(state.mediaWorld,state.competitionId);
