export function advanceSeasonDay(state:SeasonState,calendarDay=1):SeasonState{
  const league=cloneLeague(state.league),club=league.clubs.find(c=>c.id===state.selectedClubId)!;for(const currentClub of league.clubs)for(const player of currentClub.players){if(player.injuryDays>0)player.injuryDays--;player.condition=Math.min(100,player.condition+3);player.fatigue=Math.max(0,player.fatigue-4);if(player.injuryDays===0&&player.morale<95)player.morale++;}
  if(state.career?.status!=="Sem clube")applyTrainingDay(club,state.trainingPlan??DEFAULT_TRAINING_PLAN);
  const selection=normalizeMatchdaySelection({...state,league} as SeasonState,club);let livingWorld=state.livingWorld??createLivingWorld(club.name,state.competitionId),mediaWorld=hydrateMediaWorld(state.mediaWorld,state.competitionId);if(state.career?.status!=="Sem clube"){livingWorld=worldAfterDay(livingWorld,club,state.currentRound,state.baseSeed,state.competitionId);}const advancedWorld=processAdvancedDay(state.advancedWorld,league,state.selectedClubId,state.currentDate,calendarDay,state.baseSeed,state.year),worldLeagues=processWorldLeaguesThroughDate(state.worldLeagues,state.baseSeed,state.currentDate);return coordinateSeasonCalendars(processMarketRound({...state,league,lineupIds:selection.lineupIds,benchIds:selection.benchIds,livingWorld,mediaWorld,advancedWorld,worldLeagues}));
}

